#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>st;
for(int i=0;i<n;++i){long long x;scanf("%lld",&x);
if(!st.empty()&&st.back()==x)st.pop_back();else st.push_back(x);}
for(size_t i=0;i<st.size();++i){if(i)printf(" ");printf("%lld",st[i]);}
printf("\n");return 0;}

